void Player::CompleteActiveSpellScene(uint32 miscValue)
{
    uint32 latest = 0;
    for (auto const& scene : m_sceneInstanceID)
        if (scene.second == miscValue && scene.first > latest)
            latest = scene.first;
    if (latest)
        SceneCompleted(latest);
}

